def acceptance_probability(delta: float, temp: float) -> float:
    """Metropolis acceptance probability exp(-delta / temp) from a short Taylor series (x > -8)."""
    x: float = -delta / temp
    if x < -8.0:
        return 0.0
    term: float = 1.0
    total: float = 1.0
    for k in range(1, 18):
        term = term * x / k
        total += term
    return max(0.0, total)

